import { useState } from 'react';
import type { FormEvent } from 'react';
import { JxStepper, JxInputField, JxButton } from '@jinx-ui/react';

interface RegistrationData {
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  street: string;
  city: string;
  zip: string;
}

interface RegistrationWizardProps {
  onSubmit: (data: RegistrationData) => void;
}

const STEPS = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

export default function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [step, setStep] = useState(0);
  const [data, setData] = useState<RegistrationData>({
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    street: '',
    city: '',
    zip: '',
  });

  const update = (field: keyof RegistrationData) => (event: React.ChangeEvent<HTMLInputElement>) => {
    setData((prev) => ({ ...prev, [field]: event.target.value }));
  };

  const isLastStep = step === STEPS.length - 1;

  const handleNext = () => {
    if (!isLastStep) setStep((s) => s + 1);
  };

  const handleBack = () => {
    if (step > 0) setStep((s) => s - 1);
  };

  const handleSubmit = (event: FormEvent) => {
    event.preventDefault();
    onSubmit(data);
  };

  return (
    <form
      onSubmit={handleSubmit}
      style={{
        maxWidth: 480,
        display: 'flex',
        flexDirection: 'column',
        gap: 24,
        padding: 24,
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        color: 'var(--jx-text)',
      }}
    >
      <JxStepper steps={STEPS} current={step} />

      {step === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          <JxInputField
            label="Имя"
            required
            value={data.firstName}
            onChange={update('firstName')}
          />
          <JxInputField
            label="Фамилия"
            required
            value={data.lastName}
            onChange={update('lastName')}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={data.email}
            onChange={update('email')}
          />
          <JxInputField
            label="Телефон"
            type="tel"
            prefix="+7"
            value={data.phone}
            onChange={update('phone')}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          <JxInputField
            label="Улица и дом"
            required
            value={data.street}
            onChange={update('street')}
          />
          <JxInputField
            label="Город"
            required
            value={data.city}
            onChange={update('city')}
          />
          <JxInputField
            label="Индекс"
            value={data.zip}
            onChange={update('zip')}
          />
        </div>
      )}

      {step === 2 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 8, color: 'var(--jx-text-2)' }}>
          <div>
            <strong style={{ color: 'var(--jx-text)' }}>Контакты:</strong> {data.firstName} {data.lastName}, {data.email}, {data.phone}
          </div>
          <div>
            <strong style={{ color: 'var(--jx-text)' }}>Адрес:</strong> {data.street}, {data.city} {data.zip}
          </div>
        </div>
      )}

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: 12 }}>
        <JxButton variant="ghost" type="button" disabled={step === 0} onClick={handleBack}>
          Назад
        </JxButton>
        {isLastStep ? (
          <JxButton variant="primary" type="submit">
            Отправить
          </JxButton>
        ) : (
          <JxButton variant="primary" type="button" onClick={handleNext}>
            Дальше
          </JxButton>
        )}
      </div>
    </form>
  );
}

